WITH base AS (SELECT *, TRIM(plan) clean_plan FROM subscriptions WHERE monthly_fee < 120 AND end_date >= '2023-04-22'), agg AS (SELECT CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END end_cohort, status, COUNT(*) num_subscriptions FROM base GROUP BY CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END, status) SELECT end_cohort, status FROM agg WHERE num_subscriptions > 9 ORDER BY status
